	}
	if mode := info.Mode().Perm(); mode != 0o600 {
		t.Fatalf("perm = %o, want 0600 (re-tightened)", mode)
	}
}

func TestSaveCredentialsRetightensLoosenedDir(t *testing.T) {
	tmp := t.TempDir()
