	})

	c := newTestClient(t, srv,
		api.WithMaxRetries(0),
		api.WithSleepFunc(func(_ context.Context, _ time.Duration) bool { return true }),
		api.WithRandInt64n(func(_ int64) int64 { return 0 }),
